if (!$json.body?.telegramChatId || !$json.body?.id || !$json.body?.status) {
  throw new Error('Invalid worker callback payload.');
}
return [{ json: $json.body }];

const job = $json;
const deliveryKey = `${job.id}:${job.status}`;
const state = $getWorkflowStaticData('global');
state.callbackDeliveries ||= {};
if (state.callbackDeliveries[deliveryKey]) return [];
return [{ json: { ...job, deliveryKey } }];

const job = $json;
const escapeHtmlCharacter = (character) =>
  character === '&' ? '&amp;' : character === '<' ? '&lt;' : character === '>' ? '&gt;' : character;
const escapeHtmlWithin = (value, limit = Number.POSITIVE_INFINITY) => {
  let output = '';
  for (const character of String(value)) {
    const escaped = escapeHtmlCharacter(character);
    if (output.length + escaped.length > limit) break;
    output += escaped;
  }
  return output;
};
const withActions = (body, actions = '') => {
  const suffix = actions ? `\n\n${escapeHtmlWithin(actions)}` : '';
  const room = Math.max(0, 4096 - suffix.length);
  return `${escapeHtmlWithin(body, room)}${suffix}`.slice(0, 4096);
};
const result = (body, actions = '') => [{ json: { chatId: job.telegramChatId, deliveryKey: job.deliveryKey, text: withActions(body, actions) } }];
if (job.result?.kind === 'learning') {
  if (job.status === 'completed' && job.result.outcome === 'proposal' && job.result.proposal) {
    const proposal = job.result.proposal;
    return result(`Yayın sonrası editoryal öğrenme tamamlandı.\n\nHafıza önerisi: ${proposal.id}\n${proposal.text}`, `Düzenle: /hafiza_duzenle ${proposal.id} <yeni-kural>\nOnayla: /hafiza_onayla ${proposal.id}\nReddet: /hafiza_reddet ${proposal.id}`);
  }
  if (job.status === 'completed' && job.result.outcome === 'none') {
    return result(`Yayın sonrası editoryal öğrenme tamamlandı.\n\nBu yayın için kalıcı bir hafıza kuralı önermeye gerek görülmedi.\n\nGerekçe: ${job.result.reason || 'Belirtilmedi.'}`);
  }
  return result(`Yazı yayında kalmaya devam ediyor. Ancak yayın sonrası editoryal öğrenme tamamlanamadı; yayın bundan etkilenmedi.\n\nÖğrenme iş no: ${job.id}\nHata: ${String(job.error || job.result.error || 'Bilinmeyen hata').slice(0, 1000)}`);
}
if (job.status === 'completed' && job.result?.kind === 'ideas') {
  const options = job.result.options.map((option, index) => `${index + 1}. ${option.title}\n${option.hook}`).join('\n\n');
  const summary = job.result.researchSummary ? `${job.result.researchSummary}\n\n` : '';
  return result(`Fikir araştırması hazır: ${job.result.theme}\n\n${summary}${options}`, `Bir fikri yazıya dönüştürmek için:\n/sec ${job.id} <seçenek-no>`);
}
if (job.status === 'completed' && job.result?.kind === 'publish') {
  const learning = job.result.learning?.status === 'failed'
    ? '\n\nYayın sonrası öğrenme başlatılamadı; yayın bundan etkilenmedi.'
    : '\n\nYayın sonrası editoryal öğrenme arka planda sürüyor.';
  return result(`Yazı yayınlandı: ${job.result.title}\n\n${job.result.url}${learning}`);
}
if (job.status === 'completed') {
  const warnings = job.result.warnings?.length ? `\n\nKontrol notları:\n• ${job.result.warnings.join('\n• ')}` : '';
  const quality = job.result.quality ? `\nKalite denetimi: geçti${job.result.quality.revisionCount ? ` (${job.result.quality.revisionCount} otomatik düzeltme)` : ''}` : '';
  const label = job.result.revisedFromJobId ? 'Revize taslak hazır' : 'Taslak hazır';
  return result(`${label}: ${job.result.title}\n\nOkuma süresi: ${job.result.readTime} dk${quality}\nÖnizleme: ${job.result.previewUrl}${warnings}`, `Düzenlemek için:\n/edit ${job.id} <talimat>\n\nYayınlamak için:\n/yayinla ${job.id}`);
}
if (job.status === 'cancelled') {
  return result(`İş iptal edildi.\n\nİş no: ${job.id}`, `Tekrar başlatmak için:\n/tekrar ${job.id}`);
}
const unsafeRetry = ['saving-draft', 'publishing'].includes(job.failureStage) || !job.failureStage;
const actions = unsafeRetry ? '' : `Güvenliyse tekrar denemek için:\n/tekrar ${job.id}`;
const guidance = unsafeRetry ? '\n\nBu iş dış sisteme yazma aşamasında kesilmiş olabilir. Tekrar denemeden önce Directus durumunu kontrol et.' : '';
return result(`İçerik işi tamamlanamadı.\n\nİş no: ${job.id}\nHata: ${String(job.error || 'Bilinmeyen hata').slice(0, 1000)}${guidance}`, actions);

const deliveryKey = $('Callback Tekrarını Engelle').first().json.deliveryKey;
const state = $getWorkflowStaticData('global');
state.callbackDeliveries ||= {};
state.callbackDeliveries[deliveryKey] = new Date().toISOString();
const entries = Object.entries(state.callbackDeliveries).sort((left, right) => String(right[1]).localeCompare(String(left[1])));
for (const [key] of entries.slice(2000)) delete state.callbackDeliveries[key];
return $input.all();
